function _drawEffectsInner(){
  try{ updateShockRings(1/60); }catch(_ue){}
  try{ if(typeof efxDraw==='function') efxDraw(); }catch(_ef){}   /* 0918: bursts, burning, geysers */
  for(const fx of pilotFx){
    if(fx.type==='chainarc'){
      // YURI's signature chain lightning — v2.3 art: a real forked bolt along the arc plus a
      // BRANCHING burst at the struck node. The old gold orb/ring nodes are gone.
      const k=clamp(fx.t/fx.dur,0,1);
      if(typeof _nchainReady==='function' && _nchainReady()){
        drawChainBolt(fx.x1,fx.y1,fx.x2,fx.y2, 1-k*0.6);
        drawChainBurst(fx.x2, fx.y2, k, 52);
      } else {
        ctx.save(); ctx.strokeStyle='#ffe66b'; ctx.lineWidth=2; ctx.globalAlpha=1-k;
        ctx.beginPath(); ctx.moveTo(fx.x1,fx.y1);
        const segs=6; for(let i=1;i<=segs;i++){ const q=i/segs;
          ctx.lineTo(fx.x1+dx*q+rnd(-6,6)*(i<segs?1:0), fx.y1+dy*q+rnd(-6,6)*(i<segs?1:0)); }
        ctx.stroke(); ctx.restore();
      }
      continue;
    }
    /* DEAD VENOM FX REMOVED (drop 0801be). This drew a venom_0_* cloud for
       pilotFx entries of type 'venom' — and NOTHING in the codebase ever pushes
       one. It was unreachable code holding the last reference to art Mike asked
       to have off the player. */
  }
  // explosions (layered circles, palette)
  for(const ex of explosions){
    const k=clamp(ex.t/ex.dur,0,1);
    /* Explosions are frame animation, never opacity animation. The authored breakup/smoke reel
       remains fully opaque through its last frame and then completes; fading the entire effect
       made enemies look as though they dissolved instead of exploding. */
    if(ex.xb){
      const fi=Math.min(ex.nf-1,Math.floor(k*ex.nf)), key=ex.xb+'_'+fi;
      if(typeof XART!=='undefined' && XART.rdy(key)){
        /* A death owns a literal 125%-of-unit animation frame. Ordinary impact/set-piece calls
           retain their existing presentation scale; only classed unit deaths use this contract. */
        const sz=(ex.max||ex.r)*(ex.cls?1.25:EXPLODE_SCALE);
        ctx.save(); ctx.globalAlpha=1;
        const im=(ex._frToxic?xartPalette(key,'#79ec27'):null)||(ex.chromiumTone!=null?hammerChromiumSheet(key,ex.chromiumTone):null)||XART.get(key),iw=im.naturalWidth||im.width,ih=im.naturalHeight||im.height,s2=sz/Math.max(iw,ih);
        if(ex.chromiumTone!=null){ctx.shadowColor=HAMMER_CHROMIUM_COLORS[ex.chromiumTone];ctx.shadowBlur=10;}
        ctx.drawImage(im,ex.x-iw*s2/2,ex.y-ih*s2/2,iw*s2,ih*s2);
        ctx.restore(); continue;
      }
    }
    if(ASSETS.ready){ const fam=ex.fam||(ex.palette==='blue'?'expb':'expr'); if(ASSETS.has(fam+'0')){ const _n=ex.nf||5; const fi=Math.min(_n-1,Math.floor(k*_n)); const sz=(ex.max||ex.r)*(ex.cls?1.25:EXPLODE_SCALE); ctx.globalAlpha=1; ASSETS.blit(fam+fi,ex.x,ex.y,sz,sz); continue; } }
    /* Unit deaths never fall back to the old canvas circles. Their authored family may still be
       decoding, but a missing frame must not turn a boss into the basic placeholder explosion. */
    if(ex.cls) continue;
    const r=ex.r*(1+k*0.4);
    const inner = ex.palette==='blue'? '#dff3ff':'#fff4c0';
    const mid   = ex.palette==='blue'? '#3a8fff':'#ff6a1e';
    const outer = ex.palette==='blue'? '#1f4fb0':'#a81f0a';
    ctx.globalAlpha=1;
    ctx.fillStyle=outer; circle(ex.x,ex.y,r);
    ctx.fillStyle=mid; circle(ex.x,ex.y,r*0.66);
    ctx.globalAlpha=1;
    ctx.fillStyle=inner; circle(ex.x,ex.y,r*0.34);
    ctx.globalAlpha=1;
  }
  // particles
  for(const p of particles){
    if(p._dbrKey)continue; // authored hull fragments have their own drawDeathDebris pass
    if(p._lmBubble){
      const k=clamp(1-p.t/p.life,0,1),s=(p.r||12)*(.72+.32*Math.sin(Math.PI*k));
      ctx.save();ctx.translate(p.x,p.y);ctx.rotate((p._lmRot||0)+p.t*.8);ctx.globalAlpha=k;
      ctx.globalCompositeOperation='lighter';laserMistAtlasBlit(ctx,'lmfx_bubble_'+((p._lmFrame||0)%8),0,0,s,s,true);ctx.restore();continue;
    }
    /* HELIX DEBRIS: the ball sprite at a fraction of its size, spinning. Drawn
       before the generic particle paths so it never falls through to a dot. */
    if(p._hxdeb){
      const _k='nhxb_'+(p._hxpal||'g')+'_'+((p._hxf||0)%4);
      if(typeof XART!=='undefined' && XART.rdy(_k)){
        const im=XART.get(_k);
        const _f=clamp(1-(p.t/p.life),0,1);
        const _sz=(p._hxsz||5)*(0.55+0.45*_f);
        ctx.save();
        ctx.globalAlpha=_f;
        ctx.translate(p.x,p.y); ctx.rotate(p._hxrot||0);
        ctx.drawImage(im,-_sz/2,-_sz/2,_sz,_sz);
        ctx.restore();
        continue;
      }
    }
    /* MECH IMPACT (drop 0731m) — the boss pack's own 6-frame hit, drawn before the generic
       particle path so it does not fall through to the spark blit. The pack's contract is that
       FX carry no boss or cannon pixels and the engine anchors them, so this is safe to place
       anywhere the shell happened to land. */
    if(p.kind==='mechimpact'){
      const F=(typeof BOFX!=='undefined'&&BOFX.mechfx&&BOFX.mechfx[p.tag]);
      const sp=F&&F.impact;
      if(sp && typeof XART!=='undefined'){
        const fi=Math.min(sp.frames-1, Math.floor(p.t*sp.fps));
        const k=p.tag+'_impact_'+fi;
        if(XART.rdy(k)){
          const im=XART.get(k), h=54, w=h*(im.naturalWidth/im.naturalHeight);
          ctx.save(); ctx.globalCompositeOperation='lighter';
          ctx.globalAlpha=clamp(1-p.t/p.life,0,1);
          ctx.drawImage(im, p.x-w/2, p.y-h/2, w, h);
          ctx.restore();
        }
      }
      continue;
    }
    const a=clamp(1-p.t/p.life,0,1);
    ctx.globalAlpha=a;
    /* REAL ART, NOT DRAWN SHAPES (drop 0724ch). Every hit used ctx.arc discs, stroked rings and
       fillRect squares — flat vector primitives sitting on top of pixel art, which is exactly the
       CSS-looking decal Mike does not want. Impacts now blit the authored 8-frame spark
       (nx_small_) and debris uses the smoke set, tinted to the particle's own colour so the
       existing per-weapon palettes still read. The primitives remain ONLY as a fallback for when
       the art has not finished loading. */
    /* THE DEDICATED DEATH-FX SET WINS (drop 0801dl).

       This block already routed particles to art — but to STAND-INS: the shockwave
       and every spark borrowed nx_small_, and debris borrowed the SMOKE set. It
       also sits above the nchunk_/nspark_/nring_ branch added in 0801de, so that
       branch was unreachable and the dedicated art never drew once. That is why
       the chunk plates came back empty even after the debris started spawning.

       CF_DeathFX-Vol.1 ships purpose-made frames for exactly these three, so they
       are used first and the nx_ borrows stay only as the not-yet-decoded
       fallback. Each chunk keeps a stable plate on p._ck so a given piece of
       debris does not flicker between shapes as it tumbles. */
    if(p.chunk && p._ck==null) p._ck='nchunk_'+((Math.abs((p.x|0)+(p.y|0)*7)|0)%8);
    if(!p.chunk && !p.flashring && p._sk==null){
      const _t=['point','glint','ember','streak'][(Math.abs((p.x|0)*3+(p.y|0))|0)%4];
      p._sk='nspark_'+_t+'_'+((Math.abs(p.y|0))%3);
    }
    /* MIKE'S OWN SHOCKWAVE AND SHRAPNEL (drop 0801ev). Mike: "your not using our
     shockwave and decal graphics i gave you, or shrapnel."

     ngm_shock_0..7 and ndbr_0..7 were registered and never drawn - of the
     23 ngm_ families in the build, 21 have zero references. fxBurst was reaching
     for nring_/nchunk_ instead, which are the smaller CF_DeathFX plates.

     Preference order is now: Mike's plate if it is registered, the DeathFX plate
     otherwise. Nothing is lost if a set is missing. */
  const _shockK = 'ngm_shock_'+Math.max(0,Math.min(7,Math.floor((Math.max(0,p.t)/p.life)*8)));
  const _shrapK = 'ndbr_'+(((p._seed||0)+Math.floor(p.t*14))%8);
  const _dfx = p.flashring
      ? ((XART._src && XART._src[_shockK]) ? _shockK
         : ('nring_'+Math.max(0,Math.min(7,Math.floor((Math.max(0,p.t)/p.life)*8)))))
      : p.chunk
      ? ((XART._src && XART._src[_shrapK]) ? _shrapK : null)
      : null;
  const _dfxOld = p.flashring ? ('nring_'+Math.max(0,Math.min(7,Math.floor((Math.max(0,p.t)/p.life)*8))))
               : p.chunk     ? p._ck
               :               p._sk;
    const _pk = (_dfx && typeof XART!=='undefined' && XART._src && XART._src[_dfx] && XART.rdy(_dfx))
              ? _dfx
              : ( p.flashring ? ('nx_small_'+Math.min(7,Math.floor((p.t/p.life)*8)))
                : p.chunk     ? (SMOKE_FAM+'_'+Math.min(7,Math.floor((p.t/p.life)*8)))
                :               ('nx_small_'+Math.min(7,Math.floor((p.t/p.life)*8))) );
    const _pim = (typeof XART!=='undefined' && XART.rdy(_pk)) ? XART.get(_pk) : null;
    if(_pim){
      const _d = p.flashring ? p.r*2.4*(0.4+0.6*(p.t/p.life))
               : p.chunk     ? Math.max(p.sw,p.sh)*3.0
               :               Math.max(6,p.r*4.2);
      const _tc = (typeof xartTint==='function' && p.color) ? xartTint(_pk, p.color, 0.62) : null;
      ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=a*0.92;
      ctx.drawImage(_tc||_pim, p.x-_d/2, p.y-_d/2, _d, _d);
      ctx.restore();
    }
    /* THE FAKE DECALS ARE GONE (drop 0801de). Mike: "when enemies dies, Ive
       noticed these fake decals?" They were canvas primitives — a stroked arc for
       the shockwave, a filled RECTANGLE for every piece of debris, a filled
       circle for every spark. Flat shapes in the unit's palette colour, which is
       exactly why they read as fake.

       CF_DeathFX-Vol.1 supplies all three as real art, palette-neutral grey, so
       each one is tinted to the unit's own colour through xartTint rather than
       being drawn AS a colour. Same technique as the hit flash and the menu
       cursors — a palette swap, never an overlay filter.

       Every particle keeps its existing physics; only the pixels change. Falls
       back to the old primitive if a frame has not decoded yet, so a cold loader
       never drops a death. */
    else if(p.flashring){
      const _rf=Math.min(7, Math.max(0, Math.floor((p.t/p.life)*8)));
      const _rk='nring_'+_rf;
      const _ri=(typeof XART!=='undefined'&&XART._src&&XART._src[_rk]&&XART.rdy(_rk))
        ? ((typeof xartTint==='function'&&p.color)?xartTint(_rk,p.color,0.9):XART.get(_rk)) : null;
      if(_ri){ const _d=p.r*2*(0.4+0.6*(p.t/p.life)); ctx.drawImage(_ri,p.x-_d/2,p.y-_d/2,_d,_d); }
      else {
        /* NEGATIVE RADIUS CRASHED THE WHOLE FRAME (drop 0801ew).

           Mike's console:
             IndexSizeError: The radius provided (-6.23852) is negative
               at drawEffects -> drawWorld -> drawScene -> loop

           ctx.arc throws on a negative radius, drawEffects is called from INSIDE
           drawWorld, and an uncaught throw there abandons the rest of the frame.
           Everything drawWorld had not yet drawn simply never appeared - which is
           why the liquids were missing on every stage while every test I ran on
           my side said the liquid layer was fine. It was fine. It was never
           reached.

           The negative radius is mine: fxBurst staggers its shock rings by
           starting them at t = -i*0.055 so they read as a sequence rather than
           one pop. I clamped the FRAME INDEX for the art path in 0801ei and
           never clamped the radius on this fallback path. */
        const _rr = p.r*(p.t/p.life);
        if(_rr > 0){ ctx.strokeStyle=p.color; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(p.x,p.y,_rr,0,TAU); ctx.stroke(); }
      }
    }
    else if(p.chunk){
      if(p._ck==null) p._ck='nchunk_'+((Math.abs((p.x|0)+(p.y|0)*7)|0)%8);
      const _ci=(typeof XART!=='undefined'&&XART._src&&XART._src[p._ck]&&XART.rdy(p._ck))
        ? ((typeof xartTint==='function'&&p.color)?xartTint(p._ck,p.color,0.75):XART.get(p._ck)) : null;
      if(_ci){
        const _w=Math.max(4,p.sw*2.2), _h=Math.max(4,p.sh*2.2);
        ctx.save(); ctx.translate(p.x,p.y); ctx.rotate((p.t||0)*6.2+(p._ck.charCodeAt(7)||0));
        ctx.drawImage(_ci,-_w/2,-_h/2,_w,_h); ctx.restore();
      } else { ctx.fillStyle=p.color; ctx.fillRect(p.x-p.sw/2,p.y-p.sh/2,p.sw,p.sh); }
    }
    else {
      if(p._sk==null){ const _t=['point','glint','ember','streak'][(Math.abs((p.x|0)*3+(p.y|0))|0)%4];
        p._sk='nspark_'+_t+'_'+((Math.abs(p.y|0))%3); }
      const _si=(typeof XART!=='undefined'&&XART._src&&XART._src[p._sk]&&XART.rdy(p._sk))
        ? ((typeof xartTint==='function'&&p.color)?xartTint(p._sk,p.color,0.85):XART.get(p._sk)) : null;
      if(_si){ const _d=Math.max(3,p.r*3.0); ctx.drawImage(_si,p.x-_d/2,p.y-_d/2,_d,_d); }
      else { ctx.fillStyle=p.color; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,TAU); ctx.fill(); }
    }
    ctx.globalAlpha=1;
  }
  // Engine rule: field announcements use the same authored arcade alphabet as score pops.
  const fieldArt=(typeof curFontArt==='function')?curFontArt():null;
  const fieldFace=(typeof uiFontArt==='function')?uiFontArt():null;
  ctx.textAlign='center';
  for(const f of floaters){
    if(f.elementCrit){
      drawElementalCritical(f);continue;
    }
    if(f.score){
      /* the stage face, with an arcade pop: 1.6x on the first frames, settling to 1 by 0.18s */
      const art=fieldArt;
      const k=clamp(f.t/0.18,0,1), pop=1+0.6*(1-k)*(1-k);
      const fade=f.t<f.life*0.55?1:clamp(1-(f.t-f.life*0.55)/(f.life*0.45),0,1);
      const H=(f.big?13:10)*pop;
      if(fieldFace&&artReady(fieldFace))stageText(fieldFace,f.txt,f.x,f.y,H,null,0,fade,.06);
      else if(art&&artReady(art))stageText(art,f.txt,f.x,f.y,H,null,0,fade,.06);
      continue;
    }
    const fade=clamp(1-f.t/f.life,0,1);
    if(fieldFace&&artReady(fieldFace))stageText(fieldFace,f.txt,f.x,f.y,13,null,0,fade,.06);
    else if(fieldArt&&artReady(fieldArt))stageText(fieldArt,f.txt,f.x,f.y,13,null,0,fade,.06);
  }
  /* the pickup announcement, over the field and in screen space (drop 0811m) */
  if(typeof drawArcadeBanner==='function') drawArcadeBanner();
  if(typeof stylishDraw==='function') stylishDraw();
  // sprite animations (e.g. tank destruction frames)
  if(typeof rbShardsDraw==='function') rbShardsDraw();   // rollerball shrapnel, over the field
  for(const sa of sprAnims){
    const k=clamp(sa.t/sa.dur,0,1); const fi=Math.min(sa.n-1, Math.floor(k*sa.n)); const nm=sa.base+fi;
    if(ASSETS.has(nm)){ const d=ASSETS.dims(nm), s=sa.size/Math.max(d.w,d.h); ASSETS.blit(nm,sa.x,sa.y,d.w*s,d.h*s); }
  }
  /* PLAYER IMPACTS (drop 0809m). One frame each, so the life is carried by scale and alpha
     rather than a reel: it punches out to full size fast and fades, which reads as a hit
     rather than a sprite that appeared. Additive, because these are sparks. */
  drawPlayerImpactEffects();
}
